    "description": "공주 석장리 구석기축제는 어린이들이 직접 체험하고 즐기며 구석기 시대 생활상의 문화를 자연스럽게 익힐 수 있는 역사문화 축제이다. 행사장 내 시설물은 구석기 시대 삶의 터전인 막집으로 조성하여 최대한 구석기시대를 연상할 수 있도록 연출되며 아이들의 호기심과 창의성을 샘솟게 하는 교육과 놀이가 결합된 다양한 체험이 축제기간 상시 운영된다. 어린이 맞춤형 체험과 더불어 젊은세대를 겨냥한 다양한 포토존은 자연속에서 힐링하며 인생샷을 남길 수 있는 기회이다. 매년 5월 석장리구석기 축제에서는 다양한 체험과 볼거리가 가득한 구석기시대로의 시",
