    "description": "광주 역사의 중심인 동구의 국가유산과 광주의 역사를 달빛 아래에서 만나보는 ‘광주 국가유산 야행’은 지역의 국가유산과 주변의 문화시설을 연계하여 다양한 역사문화체험의 기회를 제공하는 야간향유형 국가유산 테마 관광축제이다.\n국가유산의 가치 확산과 지역 관광 활성화를 위해 국가유산청이 지원하고 있으며, 광주 동구는 지난 2017년부터 이 사업을 추진해 올해로 10주년을 맞는다.\n8야(夜)로 구성된 광주 국가유산 야행은 야경(야간경관), 야로(역사투어), 야사(체험), 야화(전시), 야설(공연), 야식(음식), 야식(장터), 야숙(숙박)",
